import signal

class RateLimited:
    def __init__(self, count, max_count):
        self.count = count
        self.max_count = max_count
        self.lock = False

    def __enter__(self):
        if self.count > self.max_count:
            self.lock = True
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self.lock:
            self.lock = False

    def check(self):
        if self.count > self.max_count:
            return True
        return False

def is_rate_limited(count, max_count):
    return RateLimited(count, max_count).check()
